function type(s){return /^[○◯〇]/.test(s.trimStart())?'scene':/^[^「\n]+「/.test(s.trimStart())?'dialogue':'action'}
function markup(s){return s.split(/([A-Za-z0-9]+|[０-９！？]+)/).map(m=>/^[A-Za-z0-9]{1,2}$/.test(m)?'<span class="tcy">'+esc(m)+'</span>':/^[０-９！？]+$/.test(m)?'<span class="verticalGlyph">'+esc(m)+'</span>':esc(m)).join('')}
function paragraph(line,forced){const kind=forced||type(line);const p=document.createElement('p');p.dataset.kind=kind;p.dataset.leading=(line.match(/^[ \u3000]*/)||[''])[0];if(!line.trim()&&!forced)p.dataset.auto='true';p.className=line.trim()?kind:'';p.innerHTML=line?markup(kind==='action'?line.replace(/^[ \u3000]+/,''):line):'<br>';return p}
// Serialize logical DOM blocks, never layout-dependent innerText.
function domLines(root){
  const result=[]; let pending='';
  function flush(){if(pending){result.push({text:pending});pending=''}}
  function inline(n){if(n.nodeType===3)return n.textContent;if(n.nodeType!==1)return '';if(n.tagName==='BR')return '\n';return [...n.childNodes].map(inline).join('')}
  function visit(n){
    if(n.nodeType===3){pending+=n.textContent;return}if(n.nodeType!==1)return;
    if(n.dataset.cutId){flush();result.push({text:n.textContent,id:n.dataset.cutId});return}
    if(['P','DIV'].includes(n.tagName)){
      if(n.dataset.placeholder&&n===root.lastChild&&/^\n?$/.test(inline(n)))return;
      flush();
      if([...n.children].some(x=>['P','DIV'].includes(x.tagName))){[...n.childNodes].forEach(visit);flush();return}
      let t=inline(n);if(t.endsWith('\n'))t=t.slice(0,-1);
      const kind=n.dataset.kind||(['scene','action','dialogue'].find(k=>n.classList.contains(k)));
      for(let line of t.split('\n'))result.push({text:kind==='action'&&line.trim()?(n.dataset.leading??'　　　')+line.replace(/^[ \u3000]+/,''):line,kind});return;
    }
    if(n.tagName==='BR'){result.push({text:pending});pending='';return}
    [...n.childNodes].forEach(visit);
  }
  [...root.childNodes].forEach(visit);flush();return result;
}
function assignLines(c,records){
  if(!records.length||!records[0].id)records.unshift({text:'#C1',id:uid()});
  const seen=new Set(state.chapters.filter(x=>x!==c).flatMap(x=>x.cuts.map(cut=>cut.id)));c.cuts=[];c.formats=records.map(r=>r.id?null:(r.kind||type(r.text)));c.text=records.map((r,line)=>{if(r.id){if(seen.has(r.id))r.id=uid();seen.add(r.id);c.cuts.push({id:r.id,line});return '#C1'}return r.text}).join('\n');
}
