function issues(){const out=[];chapter().text.split('\n').forEach((line,i)=>{if(!line.trim()||ScriptModel.marker.test(line))return;const t=chapter().formats?.[i]||type(line);const add=(message,fixed)=>out.push({i,line,message,fixed});if(t==='action'&&!/^　{3}/.test(line))add('ト書きの頭を３字下げます。','　　　'+line.trimStart());if(t==='dialogue'&&!line.includes('」'))add('セリフの閉じカギ括弧を追加します。',line+'」');if(/^「/.test(line.trim()))add('セリフの前に人物名を記してください。');if(/(?<!…)…(?!…)/.test(line))add('三点リーダーを２つにそろえます。',line.replace(/(?<!…)…(?!…)/g,'……'));if(t==='action'&&/(思った|感じた|悲しい|嬉しい|気がした)/.test(line))add('心情を、表情・動作・音として表せないか検討しましょう。');if(t==='action'&&/(だった|していた|しました)。?$/.test(line))add('ト書きは現在形で表せないか確認してください。')});return out}
