$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const s=(await f.text()).replace(/^\uFEFF/,'');if(/\.json$/i.test(f.name)||/^[\s]*[\[{]/.test(s)||/json/i.test(f.type)){const incoming=validate(JSON.parse(s));modal('バックアップを復元','<p>現在の作品をバックアップとして保存し、選択した作品を開きます。キャンセルすると変更しません。</p><button id="restore" class="primary">バックアップして復元</button>');$('#restore').onclick=()=>{try{download(loadBlocked?localStorage.getItem(KEY):JSON.stringify(state,null,2),'json','application/json');if(!loadBlocked)localStorage.setItem(KEY+'-before-restore',JSON.stringify(state));else{const raw=localStorage.getItem(KEY);if(raw)localStorage.setItem(KEY+'-unreadable-recovery',raw)}state=incoming;active=state.chapters[0].id;loadBlocked=false;resetHistory();save();render();$('#dialog').close()}catch(err){toast('復元前のバックアップを保存できません。既存原稿を保護するため復元を中止しました。')}}}else{if(!/\.(txt|md)$/i.test(f.name))throw Error('未対応の形式');const c=ScriptModel.importChapter({id:uid(),title:f.name.replace(/\.(txt|md)$/i,''),status:'未着手',text:s});const starter=state.chapters[0];const replaceStarter=!loadBlocked&&!state.title&&!state.author&&state.chapters.length===1&&starter.title==='新しい章'&&starter.cuts.length===1&&!starter.text.split('\n').filter((_,i)=>i!==starter.cuts[0].line).join('').trim();if(replaceStarter){c.id=starter.id;state.chapters[0]=c}else state.chapters.push(c);active=c.id;ScriptModel.renumber(state);recordHistory();save();render();$('#dialog').close();toast('新しい章として読み込みました')}}catch(err){toast('読み込めません。JSONの形式やカット情報をご確認ください。既存原稿は変更していません。')}e.target.value=''};
